export type Card = {
  monster: string;
  rank?: number;
};

const SPHINX = "sphinx";

const BASE_TYPE_COUNT = 3;
const SPHINX_POINTS = 1;
const BASE_BONUS = 1;
const BONUS_PER_EXTRA_TYPE = 2;

const hasSphinx = (army: Card[]): boolean =>
  army.some((card) => card.monster === SPHINX);

const countDistinctMonsterTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

const countNonSphinxMonsterTypes = (army: Card[]): number =>
  countDistinctMonsterTypes(army) - 1;

const bonusForVariety = (nonSphinxTypeCount: number): number => {
  const typesBeyondBase = nonSphinxTypeCount - BASE_TYPE_COUNT;
  return typesBeyondBase > 0
    ? BONUS_PER_EXTRA_TYPE * typesBeyondBase
    : BASE_BONUS;
};

export const scoreArmy = (army: Card[]): number => {
  if (!hasSphinx(army)) return 0;
  return SPHINX_POINTS + bonusForVariety(countNonSphinxMonsterTypes(army));
};

